from decimal import Decimal, ROUND_HALF_UP

def money(value):
    return Decimal(str(value)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

def subtotal(items):
    total = Decimal(0)
    for price, quantity in items:
        if quantity < 0:
            raise ValueError("negative quantity")
        total += Decimal(str(price)) * quantity
    return total

def invoice_total(items, discount=0, tax=0):
    """Rates are fractions; discount first, then tax; round once at the end."""
    if not 0 <= discount <= 1 or tax < 0:
        raise ValueError("invalid rate")
    base = subtotal(items)
    return money(base * (1 - Decimal(str(discount))) + base * Decimal(str(tax)))

def format_invoice(items, discount=0, tax=0):
    return "$" + str(invoice_total(items, discount, tax))
